document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll(".toggle input"),t=document.querySelectorAll(".select-input"),n=document.querySelectorAll(".btn-edit"),o=document.querySelectorAll(".btn-danger"),s=document.querySelector(".btn-check-update");e.forEach(e=>{e.addEventListener("change",function(){const e=this.parentElement.nextElementSibling?.textContent||"Setting",t=this.checked?"enabled":"disabled";showToast(`${e} ${t}`,"success")})}),t.forEach(e=>{e.addEventListener("change",function(){const e=this.value;this.parentElement.querySelector(".setting-info h3");"theme"===this.name?showToast(`Theme changed to ${e}`,"success"):"language"===this.name&&showToast(`Language changed to ${e}`,"success")})}),n.forEach(e=>{e.addEventListener("click",function(){const e=this.parentElement.parentElement.querySelector(".setting-info h3")?.textContent||"Setting";showToast(`Opening ${e} editor...`,"info")})}),o.forEach(e=>{e.addEventListener("click",function(){const t=this.textContent.trim();if(t.includes("Delete")){confirm("Are you sure you want to delete your account? This action cannot be undone.")&&showToast("Account deletion initiated","warning")}else t.includes("Download")&&(e.disabled=!0,e.textContent="Preparing...",showToast("Preparing your data for download...","info"),setTimeout(()=>{e.disabled=!1,e.textContent="Download Data",showToast("Your data has been downloaded","success")},2e3))})}),s&&s.addEventListener("click",function(){s.disabled=!0,s.textContent="Checking...",showToast("Checking for updates...","info"),setTimeout(()=>{s.disabled=!1,s.textContent="You're up to date!",showToast("You are running the latest version","success"),setTimeout(()=>{s.textContent="Check for updates"},3e3)},2e3)})});